package datatable

import (
	"strings"
	"testing"

	"github.com/charmbracelet/x/ansi"
	"github.com/mattn/go-runewidth"

	"github.com/anthnel/devdesk/internal/ui/indicator"
)

// TestRule116HoldsUnderEastAsianWidth pins Rule 116 when the terminal counts
// the ambiguous-width glyphs (● ○ ◐) as 2 cells. lipgloss always counts them as
// 1, so padding that trusts lipgloss overflows the row by one cell. It mutates
// the global runewidth condition, so it must not run in parallel.
func TestRule116HoldsUnderEastAsianWidth(t *testing.T) {
	prev := runewidth.DefaultCondition.EastAsianWidth
	runewidth.DefaultCondition.EastAsianWidth = true
	t.Cleanup(func() { runewidth.DefaultCondition.EastAsianWidth = prev })

	states := append([]indicator.State{indicator.Idle}, indicator.States()...)
	for _, width := range []int{60, 120} {
		for _, st := range states {
			for _, selected := range []bool{false, true} {
				name := st.String()
				m := New(indicatorConfig(nil))
				m.Resize(width, 10)
				m.SetItems([]row{{Name: "a", State: name}, {Name: "b", State: name}})
				if selected {
					cursorOn(t, &m, "a")
				} else {
					cursorOn(t, &m, "b")
				}
				want := m.RenderedWidth()
				// Line 0 is the header: its sort arrow (▲) is ambiguous-width
				// too, which is a separate, pre-existing matter out of scope here.
				for i, l := range strings.Split(m.View(), "\n")[1:] {
					plain := ansi.Strip(l)
					if plain == "" {
						continue
					}
					if got := runewidth.StringWidth(plain); got != want {
						t.Errorf("state=%s width=%d selected=%v line %d: East Asian width %d, want %d: %q",
							name, width, selected, i, got, want, plain)
					}
				}
			}
		}
	}
}
package datatable

import (
	"go/ast"
	"go/parser"
	"go/token"
	"io/fs"
	"path/filepath"
	"strings"
	"testing"

	"github.com/charmbracelet/bubbles/table"
	"github.com/charmbracelet/lipgloss"
	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/ui/indicator"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// stateOf reads the indicator state a test row names in its State field.
func stateOf(r row) indicator.State {
	for _, s := range indicator.States() {
		if s.String() == r.State {
			return s
		}
	}
	return indicator.Idle
}

// indicatorConfig is an IndicatorColumn at 0 and two ASCII columns. cells counts
// the calls of the Size column's Cell, to prove nothing is rebuilt.
func indicatorConfig(cells *int) Config[row] {
	return Config[row]{
		Key:        func(r row) string { return r.Name },
		SortColumn: 1,
		Columns: []Column[row]{
			IndicatorColumn(stateOf, nil, nil),
			{
				Title: "Name", Sizing: SizingContent, MinWidth: 12,
				Cell: func(r row) string { return r.Name },
				Less: func(a, b row) bool { return a.Name < b.Name },
			},
			{
				Title: "Size", Sizing: SizingContent, MinWidth: 6,
				Cell: func(r row) string {
					if cells != nil {
						*cells++
					}
					return "sz"
				},
			},
		},
	}
}

func indicatorTable(t *testing.T, items ...row) Model[row] {
	t.Helper()
	m := New(indicatorConfig(nil))
	m.Resize(60, 10)
	m.SetItems(items)
	return m
}

// lineOf returns the raw rendered line holding the name.
func lineOf(t *testing.T, m *Model[row], name string) string {
	t.Helper()
	for _, l := range strings.Split(m.View(), "\n")[1:] { // [0] is the header
